"""Create and execute a cache-only, readable notebook for the completed experiment."""
import contextlib
import io
import json
from pathlib import Path

cells=[]
def md(text):cells.append({'cell_type':'markdown','metadata':{},'source':text.splitlines(keepends=True),'id':f'cell-{len(cells)}'})
def code(text):cells.append({'cell_type':'code','metadata':{},'source':text.splitlines(keepends=True),'id':f'cell-{len(cells)}','execution_count':None,'outputs':[]})
md('# Tennis commentary: end-to-end evaluation\n\nThis notebook calls `sports_events.end_to_end_eval` modules. It defaults to reading the completed cached run. Set `RUN_REMOTE = True` to execute stages (Google Cloud authentication and paid API access required). Existing identical calls are cached.\n\n**Comparison:** DL-selected frames → tuned VLM → tuned text LLM, versus Gemini 3.1 Flash-Lite receiving the complete unfiltered eight-second DL pilot clips. Scoring uses only the same 24 test clips (192 seconds, 24 reference events). Both systems are restricted to the same 192 seconds; the baseline sees complete clips while the pipeline sees selected windows. This is not a fair streaming-latency benchmark.')
code('from pathlib import Path\nimport os, sys, json\nroot = Path.cwd()\nif not (root / "src/sports_events").exists():\n    root = root.parent\nif not (root / "src/sports_events").exists():\n    raise RuntimeError("Open from the repository or its notebooks folder")\nos.chdir(root)\nsys.path.insert(0, str(root / "src"))\nfrom sports_events.end_to_end_eval import Config, prepare, run_vlm, run_pipeline, run_baseline, evaluate\nfrom sports_events.io import read_json\nRUN_REMOTE = False\nconfig = Config()\nrun = Path(config.run)\nprint(json.dumps(config.__dict__, indent=2))')
md('## 1. Freeze sources and test scope\n`prepare` checks the frozen VLM results, image hashes, commentary reference, clip membership, source video and protocol. It never passes reference labels to generation models.')
code('if RUN_REMOTE:\n    run_vlm(config)\nprotocol = prepare(config) if RUN_REMOTE else read_json(run / "protocol.json")\nprint(protocol["scope"])\nprint("Reference events:", len(protocol["reference"]))\nprint("Test clips:", len(protocol["clips"]))\nprint("Source video minutes (not sent in full):", round(protocol["video_seconds"] / 60, 2))')
md('## 2. DL → tuned VLM → tuned commentary LLM\nReuse the verified 34 VLM outputs from the prior test. Invalid/null event objects are logged and skipped without ground-truth repair. The tuned LLM sees its own accumulated commentary and the preceding two predicted events. Each new sentence is appended; histories are never replaced by reference text.')
code('pipeline = run_pipeline(config) if RUN_REMOTE else read_json(run / "pipeline.json")["segments"]\nprint("Commentary segments:", len(pipeline))\nprint(json.dumps(pipeline[:2], indent=2))\nprint("Skipped:", read_json(run / "pipeline.json")["skipped"])')
md('## 3. Complete pilot-clip baseline\nAll source frames inside the 24 pilot test intervals are retained in separate eight-second MP4 clips; video is resized to 640 pixels wide and audio is removed to avoid using broadcast speech as a shortcut. Native model video sampling still applies. The same player-reference images are supplied. The baseline model receives no event labels, test intervals or ground-truth commentary. Its own earlier generated text supplies history.')
code('baseline = run_baseline(config) if RUN_REMOTE else read_json(run / "baseline-test.json")["segments"]\nfull = read_json(run / "baseline-full.json")\nprint("Video chunks:", full["chunks_completed"], "/", full["chunks_total"])\nprint("All pilot-clip segments:", len(full["segments"]))\nprint("Segments inside test intervals:", len(baseline))\nprint(json.dumps(baseline[:2], indent=2))')
md('## 4. Semantic metrics and blinded LLM judge\nEmbeddings: `gemini-embedding-001`, SEMANTIC_SIMILARITY, 768 dimensions. Best-match cosine is constrained to the same clip and ±3 seconds; it measures similarity, not factual accuracy.\n\nJudge: independent `gemini-3.5-flash`. Candidate IDs and metadata are anonymized. Each clip is judged twice with A/B swapped. Matching must be one-to-one; full details earn 1, correct player/action with missing details earns 0.5, contradictions earn 0. Wrong named players receive no credit. Sparse-reference unsupported claims are distinguished from contradictions. Other metrics: ROUGE-L, exact repetition, fluency, coherence and order agreement.')
code('results = evaluate(config) if RUN_REMOTE else read_json(run / "results.json")\nprint(json.dumps(results, indent=2))')
md('## 5. Inspect commentary alongside the reference\nRead complete timestamped outputs in the run folder. The following is a compact, inspectable example; do not interpret an LLM judgment as a human label.')
code('clip_id = protocol["reference"][0]["clip_id"]\nfor label, rows in [("Reference", protocol["reference"]), ("Pipeline", pipeline), ("Video baseline", baseline)]:\n    print("\\n" + label + " / " + clip_id)\n    for row in rows:\n        if row["clip_id"] == clip_id:\n            print(f"{row[\'seconds\']:.3f}s: {row[\'text\']}")')
md('## 6. Tokens, timings and cost estimates\nCosts include reused VLM calls once for pipeline accounting; those were not called again. Both paths cover exactly 192 seconds of pilot clips. The old whole-match attempt did not produce baseline results and is not used here. Embeddings, availability probes, local compute, storage and any interrupted requests are not included in the estimates. See the pricing source and rates in the module.')
code('print(json.dumps(read_json(run / "usage.json"), indent=2))')
md('## Limitations and next checks\n- One reused development match and only 24 reference events.\n- Ground-truth prose is synthetic verbalization of human event labels.\n- Baseline sees complete eight-second clips; video rescaling and native sampling affect quality. Reference matching uses original annotation midpoints, while end-frame commitment stamps remain in metadata.\n- Judge and embedding models are automated proxies; inspect player/shot errors manually.\n- Compare matched-context, causal video chunks next; deduplicate DL windows; evaluate more untouched matches.\n\nImplementation: `src/sports_events/end_to_end_eval.py`, `src/sports_events/commentary_metrics.py`. Tests: `tests/test_end_to_end_eval.py`.')
md('## Completed pilot findings\nThe pipeline produced 33 entries versus 185 for direct video. Semantic soft F1 was 0.878 versus 0.508; similarity is not factual accuracy. Judge-weighted event recall was only 21.9% versus 22.9%, and neither system received full-detail credit. Exact repetition within clips was 33.3% versus 68.6%.\n\nOnly seven of the 24 clips contain the 24 reference events. Other claims remain unverified. Judge winner agreement after swapping presentation order was only 58.3%; human review is needed.\n\nEstimated inference cost: $0.356 pipeline (including reused VLM calls), $0.028 direct video. This setup does not demonstrate cost savings. Priorities: improve player/action correctness, suppress overlapping duplicate windows, reduce image input costs, and test fresh, densely annotated matches.')
namespace={};count=0
for cell in cells:
    if cell['cell_type']!='code':continue
    count+=1;buffer=io.StringIO()
    with contextlib.redirect_stdout(buffer):exec(''.join(cell['source']),namespace)
    cell['execution_count']=count
    if buffer.getvalue():cell['outputs']=[{'output_type':'stream','name':'stdout','text':buffer.getvalue().splitlines(keepends=True)}]
notebook={'nbformat':4,'nbformat_minor':5,'metadata':{'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python','version':'3.12'}},'cells':cells}
destination=Path('notebooks/end_to_end_commentary_evaluation.ipynb');destination.parent.mkdir(exist_ok=True)
destination.write_text(json.dumps(notebook,indent=2),encoding='utf-8')
print(destination)
